window.products.push({"id":112188,"name":"Frigidaire FARE1011MW Affinity 7.0 Cu. Ft. White Electric Dryer","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/51naH7x3UrL._AC_SL1214_.jpg","description":"The Frigidaire FARE1011MW Affinity 7.0 Cu. Ft. High Efficiency Fron Load Electric Dryer in white is an impressive appliance designed to make doing laundry easier. The massive internal capacity of this Fits-More dryer ensures you'll have to do less loads to get everything dry, while the TimeWise technology ensures that the drying time matches the wash time on the matching washer, guaranteeing that you'll never been waiting for your dryer to catch up again. It also features options such as One-Touch Wrinkle Release, which finishes a load by tumbling without heat to prevent wrinkles from setting in, and the Express-Select controls, which make choosing settings easy. Package Content: FARE1011MW dryermanualwarranty","images":["https://m.media-amazon.com/images/I/51naH7x3UrL._AC_SL1214_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"FRIGIDAIRE","source_asin":"B009AKAK6U","category_path":"Home & Appliances"},"sku":"BM-112188","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B009AKAK6U","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Appliances.jsonl","source_asin":"B009AKAK6U","price_pending":true,"merchant_ready":false});
